import fs from "node:fs";
import path from "node:path";
import type { EphemeraItem } from "./ephemera-types";

export * from "./ephemera-types";

/**
 * The ephemera, dated.
 *
 * Michael already gave every piece its own page; what it never had was a
 * date a reader could sort or filter by. This is the index generated by
 * scripts/extract-ephemera-items.ts, which reads the year out of his own
 * description of each piece.
 *
 * The decade galleries are not in here. They are indexes of the pieces
 * rather than pieces, and they stay linked from the foot of the page.
 */

const ROOT = process.cwd();
let cache: EphemeraItem[] | null = null;

export function getEphemeraItems(): EphemeraItem[] {
  if (cache) return cache;
  const file = path.join(ROOT, "data", "ephemera-items", "items.json");
  if (!fs.existsSync(file)) return (cache = []);
  const parsed = JSON.parse(fs.readFileSync(file, "utf8")) as { items?: EphemeraItem[] };
  return (cache = parsed.items ?? []);
}
